CREATE OR REPLACE FUNCTION public.activate_jood_owner() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id=auth.uid() AND lower(email)='eshaq9291@gmail.com' AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Owner email verification required'; END IF; sid := (auth.jwt()->>'session_id')::uuid; IF sid IS NULL THEN RAISE EXCEPTION 'Session required'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'admin') ON CONFLICT DO NOTHING; INSERT INTO public.admin_sessions(session_id,user_id,expires_at) VALUES(sid,auth.uid(),now()+interval '2 hours') ON CONFLICT(session_id) DO NOTHING; RETURN public.has_admin_access(); END $$;
REVOKE ALL ON FUNCTION public.activate_jood_owner() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.activate_jood_owner() TO authenticated;
CREATE OR REPLACE FUNCTION public.save_admin_product(_id text,_name text,_category text,_price numeric,_data jsonb,_stock integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wh uuid; oldqty integer; BEGIN IF NOT public.has_admin_access() THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(trim(_name))=0 OR _price<0 OR _stock<0 OR _stock IS NULL THEN RAISE EXCEPTION 'Invalid product'; END IF; SELECT id INTO wh FROM public.warehouses ORDER BY created_at LIMIT 1; IF wh IS NULL THEN RAISE EXCEPTION 'Warehouse required'; END IF; INSERT INTO public.products(id,name,category,price_yer,data) VALUES(_id,trim(_name),_category,_price,_data) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,price_yer=excluded.price_yer,data=excluded.data,updated_at=now(); INSERT INTO public.stock(product_id,warehouse_id,qty) VALUES(_id,wh,0) ON CONFLICT DO NOTHING; SELECT qty INTO oldqty FROM public.stock WHERE product_id=_id AND warehouse_id=wh FOR UPDATE; PERFORM public.erp_move_stock(_id,wh,_stock-oldqty,'stocktake',NULL); END $$;
REVOKE ALL ON FUNCTION public.save_admin_product(text,text,text,numeric,jsonb,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_admin_product(text,text,text,numeric,jsonb,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.delete_admin_product(_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_admin_access() THEN RAISE EXCEPTION 'Unauthorized'; END IF; DELETE FROM public.stock WHERE product_id=_id; DELETE FROM public.products WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.delete_admin_product(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.delete_admin_product(text) TO authenticated;